/**
 * Generates app/appearance-presets.css from the pure palette module.
 *
 * Run with: bun scripts/generate-appearance-css.ts
 *
 * The generated file provides the `--site-*` semantic variables for every
 * preset in both light and dark mode. Custom accent colours are applied as
 * inline custom properties on <html> by the ThemeProvider, which override
 * these static blocks. Keeping presets in CSS (rather than inline JSON) means
 * the prepaint script only has to set data attributes, with no flash and no
 * per-page payload.
 */

import { writeFile } from "node:fs/promises";
import { join } from "node:path";
import {
  DEFAULT_APPEARANCE,
  presetIds,
  presetLabels,
  resolveAppearance,
} from "../lib/appearance-palette";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const ROOT = join((import.meta as any).dir as string, "..");
const OUT = join(ROOT, "app", "appearance-presets.css");

function block(selector: string, variables: Record<string, string>): string {
  const body = Object.entries(variables)
    .filter(([key]) => key.startsWith("--site-"))
    .map(([key, value]) => `  ${key}: ${value};`)
    .join("\n");
  return `${selector} {\n${body}\n}`;
}

function appearance(theme: "light" | "dark", preset: (typeof presetIds)[number]) {
  return resolveAppearance(
    { version: 2, theme, accent: { kind: "preset", preset } },
    theme === "dark",
  ).variables;
}

async function main() {
  const parts: string[] = [
    "/* AUTO-GENERATED by scripts/generate-appearance-css.ts — do not edit by hand. */",
    "",
    "/* Default preset (indigo) so pages render correctly before hydration. */",
    block(":root", appearance("light", DEFAULT_APPEARANCE.accent.kind === "preset" ? DEFAULT_APPEARANCE.accent.preset : "indigo")),
    block('[data-site-theme="dark"]', appearance("dark", "indigo")),
    "",
  ];

  for (const preset of presetIds) {
    parts.push(`/* ${presetLabels[preset]} */`);
    parts.push(
      block(
        `[data-site-palette="${preset}"][data-site-theme="light"]`,
        appearance("light", preset),
      ),
    );
    parts.push(
      block(
        `[data-site-palette="${preset}"][data-site-theme="dark"]`,
        appearance("dark", preset),
      ),
    );
    parts.push("");
  }

  await writeFile(OUT, `${parts.join("\n")}\n`, "utf-8");
  console.log(`✓ Wrote ${OUT}`);
}

main().catch((error) => {
  console.error("Appearance CSS generation failed:", error);
  process.exit(1);
});
